  if (amt > 10000) codes.push("over_limit");

  if (row.status === "rejected") {
    const sent = ctx?.complianceSentByTxn?.get(row.transaction_id);
    if (sent) codes.push("compliance_hold");
  }

  if (row.status === "approved" && amt > 10000) {
    const approvedBy = ctx?.policyApprovedByTxn?.get(row.transaction_id);
    if (approvedBy === "compliance") codes.push("policy_waiver");
