  if (row.status === "reversed" && amt > 5000) {
    if (ctx?.statusChangedByCorrection?.has(row.transaction_id)) {
      codes.push("retroactive_review");
    }
  }

  if (!codes.length) return null;
  codes.sort();
  return codes.join(";");
}

function applyExceptions(items, ctx) {
  for (const row of items) {
    row.exception_reason = computeExceptionReason(row, ctx);
  }
  return items;
}

function buildExceptions(items) {
