write('/app/audit-extractor/src/normalize/reconcile.js', """const { sortByTransactionId } = require("../utils/sort");

const STATUS_ORDER = { pending: 0, approved: 1, rejected: 2, reversed: 3 };

function reconcileTransactions(parsed) {
  const byId = new Map();
  for (const row of parsed.ledger) {
    byId.set(row.transaction_id, { ...row });
  }

  for (const meeting of parsed.meetings || []) {
    if (!meeting.signed) continue;
    const target = byId.get(meeting.transaction_id);
    if (target) target.owner = meeting.owner;
  }

  const complianceSentByTxn = new Map();
  for (const email of parsed.emails || []) {
    const target = byId.get(email.transaction_id);
    if (!target) continue;
    target.status = email.status;
    const prev = complianceSentByTxn.get(email.transaction_id);
    if (!prev || email.sent > prev) complianceSentByTxn.set(email.transaction_id, email.sent);
  }

  const policyApprovedByTxn = new Map();
  for (const ex of parsed.policyExceptions || []) {
    if (!ex?.transaction_id) continue;
    policyApprovedByTxn.set(ex.transaction_id, String(ex.approved_by || "").trim().toLowerCase());
  }

  const notices = [...(parsed.corrections || [])].sort((a, b) =>
    a.notice_id < b.notice_id ? -1 : a.notice_id > b.notice_id ? 1 : 0,
  );

  const report = [];
  const statusChangedByCorrection = new Set();

  for (const notice of notices) {
    const target = byId.get(notice.transaction_id);
    if (!target) continue;

    const field = notice.field;
    const prevVal = target[field] != null ? String(target[field]) : "";

    if (field === "owner") target.owner = notice.value;
    else if (field === "status") {
      target.status = notice.value;
      if (prevVal.toLowerCase() !== String(notice.value).toLowerCase()) {
        statusChangedByCorrection.add(notice.transaction_id);
      }
    } else if (field === "date") target.date = notice.value;

    report.push({
      notice_id: notice.notice_id,
      transaction_id: notice.transaction_id,
      field,
      previous_value: prevVal,
      new_value: notice.value,
      effective: notice.effective,
    });
  }

  const items = sortByTransactionId(
    [...byId.values()].map((row) => ({
      transaction_id: row.transaction_id,
      owner: row.owner,
      status: String(row.status).toLowerCase(),
      effective_date: row.date,
      amount_usd: Number(row.amount),
      exception_reason: null,
    })),
  );

  report.sort((a, b) => (a.notice_id < b.notice_id ? -1 : a.notice_id > b.notice_id ? 1 : 0));

  return {
    items,
    report,
    exceptionContext: { complianceSentByTxn, policyApprovedByTxn, statusChangedByCorrection },
  };
}

module.exports = { reconcileTransactions, STATUS_ORDER };
""")

